INSERT INTO "classifications" VALUES(474,'claude-haiku-5-5','2026-10-17T08:53:13Z',1,0.8,0,'{"areas": ["forecasting"], "confidence": 0.8, "countries": ["JP"], "event_date": "2026-10-16", "institutions": [{"country": "JP", "name": "Weathernews Inc.", "short_name": "Weathernews", "type": "private_sector"}], "language": "ja", "news_type": "other", "original_title": "台風30号 AI予測は西寄り 物理モデルもAI予測に近づく傾向 - ウェザーニュース", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "Weathernews reports that the track forecast for Typhoon No. 30 differs between conventional physical models and AI forecast models, with physical models increasingly resembling AI predictions. The company says it has extended its typhoon track forecasts to as far as 10 days ahead.", "summary_original": "台風30号の進路について、従来の物理モデルとAI予測モデルで傾向に違いが見られ、物理モデルもAI予測に近づく傾向があると伝えられています。ウェザーニューズは進路予測を最大10日先まで延長したとしています。", "system_name": null, "techniques": ["ai_weather_model"], "title_en": "Typhoon No. 30 AI forecast leans west; physical models also trending toward AI forecasts - Weathernews", "value_added": "Extends typhoon track forecasts out to up to 10 days ahead, as stated by the company.", "value_types": ["lead_time"], "wmo_regions": ["II"]}');
