INSERT INTO "classifications" VALUES(2050,'copied','2026-10-22T03:09:39Z',1,0.8,0,'{"areas": ["climate_services"], "confidence": 0.8, "countries": ["NZ"], "event_date": "2026-10-20", "institutions": [], "language": "en", "news_type": "pilot_research", "original_title": "AI reveals how a warming climate will intensify NZ''s most extreme downpours", "primary_area": "climate_services", "relevant": true, "review": false, "summary_en": "A news item reports that AI has been used to show how a warming climate will intensify New Zealand''s most extreme downpours, addressing the difficulty of projecting rare record-breaking events. The snippet does not name the research institution or the specific AI method used.", "summary_original": null, "system_name": null, "techniques": ["ml_dl"], "title_en": "AI reveals how a warming climate will intensify NZ''s most extreme downpours", "value_added": "Helps understand how rare one-in-100-year extreme rainfall events could change in the future under a warming climate.", "value_types": ["accuracy", "other"], "wmo_regions": ["V"]}');
INSERT INTO "classifications" VALUES(2126,'claude-haiku-5-5','2026-10-22T03:09:23Z',0,0.97,0,'{"areas": ["other"], "confidence": 0.97, "countries": [], "event_date": "2026-10-21", "institutions": [], "language": "ja", "news_type": "other", "original_title": "半導体メモリーの27年、市場拡大続き競争激化 中国2社が台風の目", "primary_area": "other", "relevant": false, "review": false, "summary_en": "The article covers the semiconductor memory market, driven by demand from AI servers and rising prices, with two Chinese companies becoming significant competitors. It does not describe AI being used for weather, water, climate, early warning or disaster risk reduction, so it is not relevant to WMO monitoring.", "summary_original": "AIサーバー向けの需要拡大と価格上昇を背景に、半導体メモリー市場の拡大と競争激化が続くという内容の記事です。気象・防災分野でのAI活用は扱っていません。", "system_name": null, "techniques": [], "title_en": "Semiconductor memory market to keep expanding for 27 years amid intensifying competition; two Chinese firms emerge as key players", "value_added": null, "value_types": [], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(2195,'claude-haiku-5-5','2026-10-22T03:09:39Z',0,0.9,0,'{"areas": ["other"], "confidence": 0.9, "countries": ["JP"], "event_date": "2026-10-21", "institutions": [{"country": "JP", "name": "NTT", "short_name": "NTT", "type": "private_sector"}, {"country": "JP", "name": "福岡市管工事協同組合", "short_name": null, "type": "NGO"}], "language": "ja", "news_type": "pilot_research", "original_title": "NTT、光ファイバとAIで漏水位置を特定 15分で熟練者並み精度", "primary_area": "other", "relevant": false, "review": false, "summary_en": "NTT demonstrated, with the Fukuoka City pipe works cooperative, an optical fiber sensing and AI approach to locate leaks in urban water supply pipes. The reported accuracy is within 75 cm horizontally with an 88% correct rate. This is a water utility infrastructure application rather than weather, climate, early warning or disaster risk reduction, so it is not relevant to WMO monitoring.", "summary_original": "NTTは光ファイバセンシングとAIを活用し、福岡市内で給水管の漏水位置特定を実証した。水平誤差75cm以内、正解率88%を達成したという。", "system_name": null, "techniques": ["ml_dl"], "title_en": "NTT identifies water pipe leak locations with optical fiber and AI, achieving accuracy comparable to experts in 15 minutes", "value_added": "Locates water supply pipe leaks in about 15 minutes with accuracy comparable to experts (horizontal error within 75 cm, 88% correct rate).", "value_types": ["speed", "accuracy"], "wmo_regions": ["II"]}');
