INSERT INTO "classifications" VALUES(2546,'claude-haiku-5-5','2026-10-23T03:09:58Z',1,0.85,0,'{"areas": ["forecasting", "guidance"], "confidence": 0.85, "countries": ["JP"], "event_date": "2026-10-22", "institutions": [{"country": null, "name": "European Centre for Medium-Range Weather Forecasts", "short_name": "ECMWF", "type": "WMO_centre"}, {"country": "JP", "name": "Japan Meteorological Agency", "short_name": "JMA", "type": "NMHS"}], "language": "ja", "news_type": "pilot_research", "original_title": "台風30号の進路予想で試される従来予想モデルとAIの実力 欧米ではすでにAI予想も 日本は未導入（FNNプライムオンライン（フジテレビ系）） - Yahoo!ニュース", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "The article reports that Western weather agencies already operate AI-based weather forecast models, and that for a 2026 typhoon approaching Japan, AI track forecasts were rated relatively better than conventional models. Japan has not yet introduced AI forecasting in its operations, according to the article.", "summary_original": "欧米の気象機関はAIを使った気象予報モデルを運用しており、2026年に日本に接近した台風の進路予想では、従来モデルよりAIの方が比較的良好だったとの評価が紹介されている。日本は未導入とされる。", "system_name": null, "techniques": ["ai_weather_model"], "title_en": "Traditional forecast models vs AI in predicting the track of Typhoon No. 30; Europe and US already operate AI forecasts, Japan has not yet introduced them", "value_added": "AI-based models showed relatively better track forecast performance than conventional models for a typhoon approaching Japan in 2026, according to an evaluation cited in the article.", "value_types": ["accuracy"], "wmo_regions": ["II"]}');
